// Local intent matching works with Orbit disabled. A plan never mutates a project.
export function suggestSetup(project){const text=(project.description||'').toLowerCase(),changes=[];const has=re=>re.test(text);if(has(/subway|lane|runner|running|endless/))changes.push({key:'runner',label:project.dimension==='3d'?'Enable automatic running and three lanes':'Enable continuous automatic running',variables:{Lane:1,Distance:0}});if(has(/jump|platform|subway|runner/))changes.push({key:'jump',label:'Enable jumping, jump counter, and a Jump button',variables:{Jumps:0,JumpHeight:8}});if(has(/coin|collect|pickup|score/))changes.push({key:'coins',label:'Add a coins counter linked to Score',variables:{Score:0}});if(has(/health|life|lives|hazard|enemy|obstacle/))changes.push({key:'health',label:'Add health and an on-screen health bar',variables:{Health:3}});if(has(/swip|touch|mobile|subway/))changes.push({key:'swipe',label:'Map swipes: up → jump, down → slide, left/right → change lanes',variables:{}});return changes}
export function applySetupPlan(project,changes){project.variables??={};project.ui??=[];for(const c of changes){for(const[k,v]of Object.entries(c.variables||{}))if(!Object.hasOwn(project.variables,k))project.variables[k]=v;if(c.key==='runner'){if(project.dimension==='3d')project.runner={enabled:true,speed:8,lanes:3,laneWidth:2.2};else project.autoRun={enabled:true,speed:180}}if(c.key==='runner'||c.key==='swipe'||c.key==='jump'&&!project.swipeEvents?.length)project.swipeEvents=[{direction:'up',action:'jump',value:1},{direction:'down',action:'slide',value:1},{direction:'left',action:project.dimension==='3d'?'switchlane':'move',value:-1},{direction:'right',action:project.dimension==='3d'?'switchlane':'move',value:1}];const type=c.key==='jump'?'button':c.key==='health'?'bar':'counter',variable=c.key==='jump'?'Jumps':c.key==='coins'?'Score':c.key==='health'?'Health':null;if(variable&&!project.ui.some(e=>e.variable===variable&&e.type===type))project.ui.push({id:crypto.randomUUID(),type,text:c.key==='jump'?'Jump':c.key==='coins'?'Coins':'Health',variable,x:c.key==='jump'?75:3,y:c.key==='jump'?78:4+project.ui.length*11,w:22,h:10,color:'#6335a5',textColor:'#ffffff',fontSize:18,action:c.key==='jump'?'jump':'none',value:1,max:3})}return project}
export function reviewSetupPlan(project,onDone){const changes=suggestSetup(project);if(!changes.length){onDone();return}const d=document.createElement('dialog');d.className='editor-dialog';d.innerHTML='<h2>Suggested game setup</h2><p>Choose what to add. Your project changes only when you apply.</p><form>'+changes.map((c,i)=>`<label style="display:block;padding:10px"><input type="checkbox" name="change" value="${i}" checked> ${c.label}</label>`).join('')+'<div style="display:flex;gap:12px;margin-top:20px"><button type="button" id="no-suggestions">Continue without changes</button><button class="primary" type="submit">Apply selected & open studio</button></div></form>';document.body.append(d);let finished=false;const done=()=>{if(finished)return;finished=true;d.close();d.remove();onDone()};d.querySelector('form').onsubmit=e=>{e.preventDefault();applySetupPlan(project,[...d.querySelectorAll('input:checked')].map(e=>changes[+e.value]));done()};d.querySelector('#no-suggestions').onclick=done;d.oncancel=e=>{e.preventDefault();done()};d.showModal()}
